"""Ilustrações da Central de missões, recortadas da imagem de referência enviada pelo Gabriel (mascote, prancheta, ícones das missões e o selo de concluída).
Cada item: (WebP em base64, largura, altura). Módulo só de dados: nada de pasta de imagens para subir."""
from __future__ import annotations

IMAGENS = {
    "mascote": ("", 352, 257),
    "prancheta": ("", 232, 230),
    "ic_estudar": ("", 123, 123),
    "ic_meta": ("", 123, 123),
    "ic_dourado": ("", 123, 123),
    "tick": ("", 83, 83),
}


def uri(nome: str) -> str:
    return "data:image/webp;base64," + IMAGENS[nome][0]


def existe(nome: str) -> bool:
    return nome in IMAGENS
